// Evidence-backed request-path tests for the Promote leaf (Phase 3.1).
//
// Generated by scripts/research/gen-31-tests.py from the rows in api.md, which in turn come from
// docs/research/apk-endpoints.md. Each test calls the method and inspects the URL that actually
// reaches `fetch`, so a rename or a route regression fails here rather than in production.

import BandlabSDK from 'bandlab-sdk';

function makeClient(): BandlabSDK {
  return new BandlabSDK({ bearerToken: 'My Bearer Token', baseURL: 'http://127.0.0.1:4010' });
}

/** Run `fn`, capture the URL of the first request, and answer it with a stub response. */
async function captureURL(fn: (c: BandlabSDK) => Promise<unknown>): Promise<string> {
  const calls: string[] = [];
  const realFetch = globalThis.fetch;
  globalThis.fetch = (async (input: any) => {
    calls.push(typeof input === 'string' ? input : input?.url ?? String(input));
    return new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof fetch;
  try {
    await fn(makeClient()).catch(() => undefined);
  } finally {
    globalThis.fetch = realFetch;
  }
  if (!calls.length) throw new Error('no request was issued');
  return calls[0]!;
}

describe('Promote paths match the APK evidence', () => {
  test('GET /beats-promo-banners hits /beats-promo-banners', async () => {
    const url = await captureURL((c) => c.promote.listBeatsPromoBanners({}));
    expect(url).toContain('/beats-promo-banners');
  });

  test('GET /populated-opportunities-banners hits /populated-opportunities-banners', async () => {
    const url = await captureURL((c) => c.promote.listOpportunitiesBanners({}));
    expect(url).toContain('/populated-opportunities-banners');
  });

  test('GET /users/{userID}/boost-credits hits /users/{userID}/boost-credits', async () => {
    const url = await captureURL((c) =>
      c.promote.retrieveBoostCredits('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'),
    );
    expect(url).toContain('/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/boost-credits');
  });

  test('GET /users/{userId}/fan-reach/fans/{initiatorID} hits /users/{userId}/fan-reach/fans/{initiatorID}', async () => {
    const url = await captureURL((c) =>
      c.promote.retrieveFanReach('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {
        userId: '182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e',
      }),
    );
    expect(url).toContain(
      '/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/fan-reach/fans/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e',
    );
  });

  test('GET /users/{userID}/payout-methods/tipalti/balance hits /users/{userID}/payout-methods/tipalti/balance', async () => {
    const url = await captureURL((c) =>
      c.promote.retrievePayoutBalance('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'),
    );
    expect(url).toContain('/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/payout-methods/tipalti/balance');
  });

  test('GET /users/{userID}/payout/method-required hits /users/{userID}/payout/method-required', async () => {
    const url = await captureURL((c) =>
      c.promote.retrievePayoutMethodRequired('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'),
    );
    expect(url).toContain('/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/payout/method-required');
  });

  test('GET /users/{userID}/promo hits /users/{userID}/promo', async () => {
    const url = await captureURL((c) => c.promote.retrievePromo('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {}));
    expect(url).toContain('/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/promo');
  });

  test('GET /users/{userID}/promo-campaigns hits /users/{userID}/promo-campaigns', async () => {
    const url = await captureURL((c) =>
      c.promote.listPromoCampaigns('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e', {}),
    );
    expect(url).toContain('/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/promo-campaigns');
  });

  test('GET /users/{userID}/promo-campaigns hits /users/{userID}/promo-campaigns', async () => {
    const url = await captureURL((c) =>
      c.promote.listBeatsCarouselCampaigns('182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e'),
    );
    expect(url).toContain('/users/182bd5e5-6e1a-4fe4-a799-aa6d9a6ab26e/promo-campaigns');
  });
});
